import React from 'react';
import CDropdown from '..';
import CTag from '../../CTag';
import CStatus from '../../CStatus';

export default () => {
  const textList = ['Basic1', 'Basic2', 'Basic3'];
  const statusList = ['usable', 'error', 'warning', 'running', 'loading', 'wait', 'disable'] as const;

  return (
    <div>
      <p style={{ fontSize: 20 }}>CStatus下拉菜单</p>
      <CDropdown
        component={CStatus}
        labelKey="text"
        valueKey="text"
        defaultValue="usable"
        options={statusList?.map(item => ({ text: item, status: item }))}
      />

      <p style={{ marginBottom: 10, fontSize: 20 }}>CTag下拉菜单</p>
      <CDropdown
        component={CTag}
        labelKey="children"
        valueKey="children"
        defaultValue="Basic1"
        options={textList?.map(item => ({ children: item }))}
      />
    </div>
  );
};

import React from 'react';
import CDropdown from '..';
import CStatus from '../../CStatus';
import type { StatusType } from '../../CStatus/interface';

export default () => {
  const positions = ['bl', 'bottom', 'br', 'tl', 'top', 'tr'] as const;
  const statusList = ['usable', 'error', 'warning', 'running加长版', 'loading加长版', 'wait', 'disable'];

  return (
    <div style={{ height: '50px' }}>
      {positions.map((position, index) => (
        <CDropdown
          key={index}
          component={CStatus}
          position={position}
          labelKey="text"
          valueKey="text"
          defaultValue="usable"
          options={statusList?.map(item => ({ text: item, status: item as StatusType }))}
        />
      ))}
    </div>
  );
};

