import React, { useState } from 'react';
import { Form } from '@arco-design/web-react';
import CDropdown from '..';
import CStatus from '../../CStatus';
import type { CStatusProps } from '../../CStatus/interface';

export default () => {
  const statusList = ['usable', 'error', 'warning', 'running', 'loading', 'wait', 'disable'] as const;
  const [value, setValue] = useState('warning');

  return (
    <div>
      <p style={{ fontSize: 20 }}>设置默认值为第二项</p>
      <CDropdown
        component={CStatus}
        labelKey="text"
        valueKey="text"
        defaultValue="error"
        options={statusList?.map(item => ({ text: item, status: item }))}
      />
      <p style={{ marginBottom: 10, fontSize: 20 }}>可控模式</p>
      <CDropdown
        component={CStatus}
        labelKey="text"
        valueKey="text"
        value={value}
        onChange={(value: string) => {
          console.log('value-----', value);
          setValue(value);
        }}
        options={statusList?.map(item => ({ text: item, status: item }))}
      />
      <p style={{ marginBottom: 10, fontSize: 20 }}>自定义组件</p>
      <CDropdown
        component={(props: CStatusProps) => <CStatus {...props} type="highlight" />}
        labelKey="text"
        valueKey="text"
        defaultValue="usable"
        options={statusList?.map(item => ({ text: item, status: item }))}
      />
      <p style={{ marginBottom: 10, fontSize: 20 }}>在form中使用</p>
      <Form>
        <Form.Item>
          <CDropdown
            component={CStatus}
            labelKey="text"
            valueKey="text"
            value={value}
            onChange={(value: string) => {
              console.log('value-----', value);
              setValue(value);
            }}
            options={statusList?.map(item => ({ text: item, status: item }))}
          />
        </Form.Item>
      </Form>
    </div>
  );
};

